// W7: catalog of the screens that exist ONLY in the Next.js front end (pema-agent/frontend), not in the old web.
// Groups: WJ agent admin (/admin/* except /admin/care), WK care agent (/admin/care/*, /care/*), WL sign-in, shell and
// message templates. Merged into the main catalog by lib/catalog.cjs; web-inventory.cjs writes them to inventory.json with
// `source: "nextjs"`.
//
// Ids are frozen once committed: never renumber, append new ids at the end of their group. Within this file the numbers
// are handed out in reading order by `add()`, so insert new entries only at the END of a group's block.
//
// What is NOT walked here: the old-web walk (web-inventory.cjs) skips these entries. They are checked statically instead:
// `next_route` must be a real `page.tsx` under src/app, and every page.tsx (except /dev/kit) must be claimed by an entry or
// by `non_screens_nextjs`. Live reach (shots, snapshot) is W8/W9 work against the mock back end.
//
// `reach` is a description for W8, not an old-web step list. Vocabulary (all run against `pnpm dev:mock`, base
// http://127.0.0.1:3000):
//   { login: '<role>' }            sign in as the mock account of the role (owner, manager, doctor, cs_staff, reception, patient)
//   { goto: '/path' }              open a route
//   { button: 'Name' }             click the button or link with this accessible name
//   { text: 'Label' }              click the element showing this text (chip, tab, row)
//   { fill: ['Label', 'value'] }   fill the field with this label
//   { wait: 'Text' }               wait until the text is visible
//   { note: '…' }                  a state that needs data or a condition the mock does not give by default
// `expect.text` is a string the screen shows (verbatim). Roles are the mock roles of mock/auth.ts (the back end decides
// the real matrix). Every string below was read from the code; nothing is invented. Notes carry the gate (permission),
// the tests that cover the screen, and the texts a designer must keep.

const FE = 'pema-agent/frontend/src';
const ADM = `${FE}/app/(admin)/admin`;
const CARE = `${FE}/app/(admin)/care`;
const APP = `${FE}/app/(admin)`;
const CMP = `${FE}/components`;

const groups = [
  { code: 'WJ', name: 'Quản trị agent (Next.js)' },
  { code: 'WK', name: 'Agent chăm sóc (Next.js)' },
  { code: 'WL', name: 'Đăng nhập, khung & mẫu tin (Next.js)' },
];

const screens = [];
const counters = { WJ: 0, WK: 0, WL: 0 };

// add(group, name, kind, route, role, reach, expectText, sources, notes, extra)
function add(group, name, kind, route, role, reach, expectText, sources, notes, extra = {}) {
  counters[group] += 1;
  screens.push({
    id: `${group}${counters[group]}`,
    group,
    name,
    kind,
    role: role || 'anonymous',
    reach,
    expect: { text: expectText },
    sources,
    next_route: route,
    next_status: 'restyle (U1)',
    app_canvas: [],
    legacy_shot: null,
    covers: [],
    notes,
    source: 'nextjs',
    ...extra,
  });
}

const as = (role, route) => [{ login: role }, { goto: route }];
const MOBILE = { viewport: [390, 844], frames: ['390x844'] };
const SHELL = [`${CMP}/admin/layout/app-shell.tsx`, `${FE}/lib/nav.tsx`];

